import 'package:flutter_test/flutter_test.dart'; import 'package:shared_preferences/shared_preferences.dart'; import 'package:eye_control/presentation/providers/settings_provider.dart'; void main(){test('loads and persists settings',()async{SharedPreferences.setMockInitialValues({'settings.dark':true,'settings.language':'en','settings.dwellMs':1200});final s=SettingsProvider();await s.load();expect(s.darkMode,isTrue);expect(s.locale.languageCode,'en');expect(s.dwellMs,1200);await s.setDwellMs(1500);expect(s.dwellMs,1500);});}